<?php declare(strict_types=1);
ini_set('zend.exception_ignore_args','1');
require dirname(__DIR__).'/native/bootstrap.php';
require __DIR__.'/support/original-database-hash.php';
use Kulturhus\Native\Cms\{Articles,Conflict,DataModel,Media,Pages,Schema};
use Kulturhus\Native\Shared\{Access,Db};
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Web\{Articles as ArticleView,Manager};
use Kulturhus\Native\Web\Website\{NewsReadingView,PageEditor,VersionValues};
$checks=[];
function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks[]=$label;}
function rejects(callable $f,string $label):void{try{$f();}catch(DomainException|InvalidArgumentException|Conflict $e){check(true,$label);return;}throw new RuntimeException('FAIL: accepted '.$label);}
$db=TestSupport::db();TestSupport::seed($db);Schema::install($db);
$admin=new Access($db,'admin');$reader=new Access($db,'reader');$foreign=new Access($db,'outsider');
Db::run($db,"INSERT INTO native_grants VALUES('reader','website','publish')");
$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/reading-media';$media=new Media($db,$admin,$root);$model=new DataModel($db,$admin);$pages=new Pages($db,$admin);$articles=new Articles($db,$admin);
$images=[];foreach([[255,0,0],[0,255,0],[0,0,255]]as$i=>$rgb){$im=imagecreatetruecolor(96,48);imagefill($im,0,0,imagecolorallocate($im,...$rgb));$source=$root.'/own-'.$i.'.png';imagepng($im,$source);imagedestroy($im);$images[]=$media->upload($source,'own-'.$i.'.png','Ursprüngliches Foto '.$i.' & <Kunst>')['id'];unlink($source);}
$target=$pages->save(['title'=>'Eigenes gespeichertes Seitenziel','slug'=>'own-reference']);
$definitions=[['key'=>'own_rich','label'=>'Ursprünglich formatiert','type'=>'richtext'],['key'=>'own_flag','label'=>'Genaues Nein','type'=>'boolean'],['key'=>'own_decimal','label'=>'Exakter Dezimalwert','type'=>'decimal'],['key'=>'own_page','label'=>'Eigene Seite','type'=>'page-reference'],['key'=>'own_image','label'=>'Eigenes Zusatzbild','type'=>'media-reference'],['key'=>'own_empty','label'=>'Ursprünglich leer','type'=>'text']];
foreach($definitions as$d)$model->saveField($d);
$template=$model->template('news');$template['fields']=array_column($definitions,'key');$model->saveTemplate($template,$template['version']);
$item=$articles->save(['title'=>'Gespeicherter Beitrag & <Original>','slug'=>'aktuelles/reading-original','news_date'=>'2050-02-03','excerpt'=>'Ursprünglicher Kurztext','body_html'=>'<p>Genaue <strong>Originalfassung</strong></p>','news_channels'=>['rss'],'media_ids'=>$images,'seo_title'=>'Ursprünglicher SEO-Titel','seo_description'=>'Ursprüngliche SEO-Beschreibung','noindex'=>true,'nav_visible'=>false,'nav_label'=>'Ursprüngliches Menü','nav_order'=>7,'parent_id'=>$target['id'],'custom_fields'=>['own_rich'=>'<p>Genaue <em>alte Formatierung</em></p>','own_flag'=>false,'own_decimal'=>'1234.5000','own_page'=>$target['id'],'own_image'=>$images[2],'own_empty'=>null]]);
$id=$item['id'];$view=new NewsReadingView($db,$reader,$root);
$tables=['khcms_pages','khcms_revisions','khcms_media','native_users','native_grants'];$before=ownOriginalDatabaseHash($db,$tables);$files=[];foreach($images as$image)$files[$image]=hash_file('sha256',$media->variant($image,'medium')['path']);
$html=$view->render($id,$item['version']);$dom=new DOMDocument();@$dom->loadHTML('<?xml encoding="UTF-8">'.$html);$xpath=new DOMXPath($dom);
check($xpath->query('//*[@data-news-reading]')->length===1&&str_contains($html,'data-source-version="1"'),'read view identifies exact saved original version');
check(str_contains($dom->textContent,'Gespeicherter Beitrag & <Original>')&&$dom->getElementsByTagName('script')->length===0,'original title markup stays inert');
check($xpath->query('//time[@datetime="2050-02-03"]')->length===1&&str_contains($dom->textContent,'03.02.2050'),'stored news date is visible without inventing current time');
check(str_contains($dom->textContent,'RSS-Feed')&&!str_contains($dom->textContent,', Website'),'exact RSS-only channel choice is visible');
check(str_contains($html,'<strong>Originalfassung</strong>')&&str_contains($html,'Ursprünglicher Kurztext'),'exact stored formatted body and excerpt remain visible');
check($xpath->query('//section[@aria-label="Gespeicherte Bilder"]//img')->length===3,'every original image remains in its stored order');
$urls=[];foreach($xpath->query('//section[@aria-label="Gespeicherte Bilder"]//img')as$node)$urls[]=$node->getAttribute('src');
check($urls===array_map(static fn($id)=>'/media-preview/'.$id.'/medium',$images),'private image URLs retain exact ordered original IDs');
check(!str_contains($html,'src="/media/')&&!str_contains($html,$root),'private images expose no public fallback or filesystem path');
check($xpath->query('//img[@alt="Ursprüngliches Foto 0 & <Kunst>"]')->length===1,'exact original alternative text is escaped without reinterpretation');
check(str_contains($html,'Weitere Bilder (2)')&&str_contains($html,'aria-label="Weitere gespeicherte Bilder"'),'remaining originals stay in bounded accessible gallery');
check($xpath->query('//*[@data-news-reading-field="own_rich"]//em')->length===1,'stored rich field type preserves its exact formatting');
check(str_contains($xpath->query('//*[@data-news-reading-field="own_flag"]')->item(0)->textContent,'Nein'),'false is displayed as false rather than missing');
check(str_contains($xpath->query('//*[@data-news-reading-field="own_decimal"]')->item(0)->textContent,(string)$item['custom_fields']['own_decimal']),'stored normalized decimal representation stays exact');
check(str_contains($xpath->query('//*[@data-news-reading-field="own_page"]')->item(0)->textContent,'Eigenes gespeichertes Seitenziel')&&!str_contains($dom->textContent,$target['id']),'owned reference has readable label without technical IDs');
check($xpath->query('//*[@data-news-reading-field="own_image"]//img')->length===1,'private referenced original image is actually displayed');
check(str_contains($xpath->query('//*[@data-news-reading-field="own_empty"]')->item(0)->textContent,'Keine Angabe'),'stored null remains distinguishable from false');
foreach(['Ursprünglicher SEO-Titel','Ursprüngliche SEO-Beschreibung','Ursprüngliches Menü','Suchmaschinen ausschließen','Menüreihenfolge','Übergeordnete Seite']as$fact)check(str_contains($dom->textContent,$fact),'saved publication metadata remains available: '.$fact);
check($xpath->query('//form|//input|//textarea|//select')->length===0,'reading presentation provides no editable controls or posting forms');
check(ownOriginalDatabaseHash($db,$tables)===$before,'reading every saved value preserves all original database bytes');
foreach($images as$image)check(hash_file('sha256',$media->variant($image,'medium')['path'])===$files[$image],'private viewing preserves exact original image bytes');
$articleHtml=(new ArticleView($db,$reader,$root,'csrf'))->manager($id);
check(str_contains($articleHtml,'data-news-reading')&&str_contains($articleHtml,'Beitrag ansehen')&&!str_contains($articleHtml,'value="article-save"'),'publisher-only actual article editor uses complete read view');
check(str_contains($articleHtml,'href="#news-review-panel"')&&str_contains($articleHtml,'id="news-review-panel"'),'article provides direct native jump to actual review section');
$general=(new PageEditor($db,$reader,$root,'csrf'))->manager($id);
check(str_contains($general,'data-news-reading')&&str_contains($general,'href="#news-review-panel"'),'general page editor shares the complete news reader and review jump');
$ordinary=(new PageEditor($db,$reader,$root,'csrf'))->manager($target['id']);
check(!str_contains($ordinary,'data-news-reading')&&!str_contains($ordinary,'href="#news-review-panel"'),'ordinary readonly page keeps its own existing flow');
$embedded=(new \Kulturhus\Native\Integration\EmbeddedManager(new Manager($db,$reader,$root,'csrf'),$reader))->main('news',$id);
check(str_contains($embedded,'native_endpoint=media-preview')&&!str_contains($embedded,'src="/media-preview/'),'integrated reader rewrites private image routes to current authenticated endpoint');
check(!str_contains($embedded,'href="/media-preview/')&&str_contains($embedded,'data-native-media'),'integrated large private image links use protected manager route without AJAX navigation');
$value=(new VersionValues($db,$reader))->render(['type'=>'page-reference','value'=>$target['id']]);
check(str_contains($value,$target['id']),'historical comparison retains its existing exact-reference identity by default');
$field=$model->field('own_rich');$model->saveField(array_replace($field,['label'=>'Niemals die neue Feldbezeichnung','type'=>'text']),$field['version']);
$html=$view->render($id,$item['version']);
check(str_contains($html,'Ursprünglich formatiert')&&!str_contains($html,'Niemals die neue Feldbezeichnung')&&str_contains($html,'<em>alte Formatierung</em>'),'schema edits do not replace the original saved label or field type in the reader');
rejects(fn()=>$view->render($id,0),'reader requires an actual saved version');
rejects(fn()=>$view->render($id,$item['version']+1),'reader cannot label a different saved revision as the requested version');
rejects(fn()=>$view->render($target['id'],$target['version']),'news reader cannot silently reinterpret another content type');
try{(new NewsReadingView($db,$foreign,$root))->render($id,$item['version']);throw new LogicException('Foreign source accepted.');}catch(RuntimeException $e){check($e->getMessage()==='Seite nicht gefunden.','foreign club cannot read saved content or images');}
Db::run($db,"DELETE FROM native_grants WHERE actor_id='reader' AND module='website' AND capability='read'");
rejects(fn()=>$view->render($id,$item['version']),'current read revocation applies to an existing view object');
Db::run($db,"INSERT INTO native_grants VALUES('reader','website','read')");
Db::run($db,"UPDATE native_users SET active=0 WHERE id='reader'");rejects(fn()=>$view->render($id,$item['version']),'disabled reader cannot inspect an old original');Db::run($db,"UPDATE native_users SET active=1 WHERE id='reader'");
$path=$media->variant($images[0],'medium')['path'];$oldBytes=file_get_contents($path);unlink($path);
check(str_contains($view->render($id,$item['version']),'Bild aktuell nicht verfügbar.'),'missing private image is reported explicitly without substituting another source');file_put_contents($path,$oldBytes);
echo json_encode(['passed'=>count($checks),'checks'=>$checks,'live_transport'=>false],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)."\n";
